import { chromium } from 'playwright';
const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:5173', { waitUntil: 'networkidle' });
const btn = page.getByRole('button', { name: 'Показать уведомление' });
const box = await btn.boundingBox();
console.log('button box', box, 'viewport 1280x800');
await btn.click();
await page.getByText('Кнопка нажата 1 раз(а)').waitFor({ timeout: 2000 });
console.log('toast visible after click: yes');
await btn.click();
await page.waitForTimeout(300);
console.log('toasts after 2 clicks:', await page.getByText(/Кнопка нажата \d+ раз/).count());
await page.screenshot({ path: '/tmp/e2e/shot-visible.png' });
const t0 = Date.now();
await page.getByText(/Кнопка нажата \d+ раз/).first().waitFor({ state: 'detached', timeout: 10000 }).catch(() => {});
await page.waitForFunction(() => !document.body.innerText.includes('Кнопка нажата'), null, { timeout: 10000 });
console.log('toasts gone after ~', Date.now() - t0, 'ms');
console.log('errors:', errors);
await browser.close();
EOF
